def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    opp_c = n - opp_d
    my_prev, opp_prev = history[-1]

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    opp_c_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        opp_c_streak += 1
        i -= 1

    w = 10 if n >= 10 else n
    recent_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recent_d += 1

    d_runs = 0
    max_d_run = 0
    run = 0
    for _, b in history:
        if b == 'D':
            run += 1
        else:
            if run > 0:
                d_runs += 1
                if run > max_d_run:
                    max_d_run = run
            run = 0
    if run > 0:
        d_runs += 1
        if run > max_d_run:
            max_d_run = run

    myD_oppC = 0
    myD_oppD = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                myD_oppC += 1
            else:
                myD_oppD += 1

    persistent = False
    if n >= 5 and opp_c == 0:
        persistent = True
    if n >= 8 and opp_d >= n - 1:
        persistent = True
    if n >= 12 and opp_d_streak >= 5:
        persistent = True
    if n >= 15 and recent_d >= 8:
        persistent = True
    if n >= 20 and opp_d * 5 >= n * 3 and opp_d_streak >= 3:
        persistent = True

    short_burst = False
    if n >= 12 and d_runs >= 3 and max_d_run <= 2 and recent_d >= 3:
        if myD_oppC >= myD_oppD:
            short_burst = True
    if n >= 18 and d_runs >= 4 and max_d_run <= 3 and recent_d >= 4:
        if myD_oppC >= myD_oppD:
            short_burst = True

    if persistent:
        return 'D'

    if short_burst:
        return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n >= 20:
                return 'D'
            return 'C'
        if myD_oppC >= 2:
            return 'D'
        if my_prev == 'D':
            return 'C'
        if myD_oppC == 1:
            return 'D'
        return 'C'

    if n >= 98:
        if opp_d * 2 >= n:
            return 'D'
        if opp_d <= 4 and opp_c_streak >= 8 and myD_oppC > myD_oppD:
            return 'D'
        if opp_prev == 'D' and opp_d_streak <= 2 and opp_d * 4 <= n:
            return 'C'
        return 'C'

    if opp_prev == 'D':
        if opp_d_streak <= 4 and opp_d <= 4:
            return 'C'
        if opp_d_streak <= 2 and opp_d <= max(2, n // 8) and recent_d <= 4:
            return 'C'
        if my_prev == 'D' and opp_d_streak <= 3 and opp_d * 2 <= n and opp_c >= max(5, n // 2):
            return 'C'
        return 'D'

    if opp_d <= 4 and opp_c_streak >= 12 and myD_oppC > myD_oppD and n >= 25:
        return 'D'
    if opp_d * 3 >= n * 2 and opp_d >= 5:
        return 'D'

    return 'C'
